mapper.select:
SELECT distinct V.ID, V.VISITOR_NAME, V.VISITOR_PHOTO_ID, V.VISITOR_PHONE, V.COMPANY, V.STATUS, V.DEVICE_STATUS, V.IS_VEHICLE, V.CAUSE, V.START_TIME, V.PERSON_TYPE, V.END_TIME, V.RECEPTIONIST_BADGE, V.RECEPTIONIST_NAME, V.RECEPTIONIST_PHONE, SAV.PLATE VEHICLE_PLATE, V.CERT_NO VISITOR_CERT_NO, S.COMP_NAME, S.DEP_NAME, S.JOB_NAME, P.PARK_NAME, V.PARK_ID, V.APPLY_TYPE, V.CREATE_TIME FROM SMT_ADMITTANCE_APPLY V LEFT JOIN SMT_STAFF S ON V.RECEPTIONIST_BADGE = S.BADGE LEFT JOIN SMT_PARK P ON V.PARK_ID=P.ID LEFT JOIN SMT_ADMITTANCE_FELLOW SAF ON SAF.VISITOR_ID = V.ID LEFT JOIN SMT_ADMITTANCE_VEHICLE SAV ON SAV.VISITOR_ID = V.ID
V.VISITOR_NAME LIKE CONCAT(CONCAT('%',#{query.visitorName}),'%')
and V.VISITOR_PHONE LIKE CONCAT(CONCAT('%',#{query.visitorPhone}),'%')
and V.receptionist_name LIKE CONCAT(CONCAT('%',#{query.receptionistName}),'%')
and V.COMPANY LIKE CONCAT(CONCAT('%',#{query.company}),'%')
and SAF.CERT_NO LIKE CONCAT(CONCAT('%',#{query.certNo}),'%')
and V.STATUS =#{query.status}
and V.APPLY_TYPE =#{query.applyType}
and V.IS_VEHICLE =#{query.isVehicle}
and V.CAUSE =#{query.cause}
and S.COMP_ID =#{query.compId}
and S.DEP_ID =#{query.depId}
and V.PARK_ID =#{query.parkId}
and V.START_TIME between to_date(#{query.startTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.endTime},'yyyy-mm-dd hh24:mi:ss')
and V.PARK_ID in
#{item}
ORDER BY V.CREATE_TIME DESC, V.START_TIME DESC

select S.ID,S.NAME,S.BADGE,S.JCHE_ID, S.JCHE_NAME JCHENAME from SMT_STAFF S

inner join SMT_PARK_BU B

on S.COMP_ID = B.COMP_ID

where
S.STATUS <> 0

	AND S.NAME=#{query.receptionistName}


	AND S.PHONE=#{query.receptionistPhone}


	AND B.PARK_ID=#{query.parkId}

select S.ID,S.NAME,S.BADGE,S.JCHE_ID, S.JCHE_NAME JCHENAME from SMT_STAFF S

inner join SMT_ORGANIZE_RELATION B

on S.COMP_ID = B.ID

where
S.STATUS <> 0

	AND S.NAME=#{query.receptionistName}


	AND S.PHONE=#{query.receptionistPhone}


	AND B.PARK_ID=#{query.parkId}

SELECT COUNT(1)
FROM SMT_ADMITTANCE_APPLY A
INNER JOIN SMT_ADMITTANCE_FELLOW F ON F.VISITOR_ID = A.ID
WHERE F.CERT_NO = #{certNo}
	AND F.IS_MAIN = 1
	AND A.STATUS != 1
	AND A.START_TIME < #{endTime}
	AND A.END_TIME > #{startTime}
